package text

import (
	"image"
	"image/color"
	"os"
	"testing"
)

// colrFixtures are the fixed COLRv0 fonts generated by
// artifacts/colr_tools/gen_fixtures.py.
const (
	colrSynthFixture  = "testdata/colr_synth.ttf"
	colrPixelsFixture = "testdata/colr_pixels.ttf"
)

func loadCOLRSource(t *testing.T, path string) *FontSource {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Skipf("COLR fixture %s unavailable: %v", path, err)
	}
	src, err := NewFontSource(data)
	if err != nil {
		t.Fatalf("NewFontSource(%s): %v", path, err)
	}
	t.Cleanup(func() { _ = src.Close() })
	return src
}

// countAlphaPixels returns the number of non-transparent pixels.
func countAlphaPixels(img *image.RGBA) int {
	n := 0
	b := img.Bounds()
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			if img.RGBAAt(x, y).A != 0 {
				n++
			}
		}
	}
	return n
}

func TestCOLR_DetectsColorFontAndGlyphType(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)
	parsed := src.Parsed()

	cf, ok := parsed.(ColorFont)
	if !ok {
		t.Fatal("ownParsedFont must implement ColorFont")
	}
	if !cf.HasColorTables() {
		t.Fatal("HasColorTables = false for COLR font")
	}
	if pf, ok := parsed.(interface{ NumColorPalettes() int }); !ok || pf.NumColorPalettes() != 2 {
		t.Fatalf("NumColorPalettes = %d, want 2", pf.NumColorPalettes())
	}

	// gid 2 is the layered U+E000; gid 0 (.notdef) is a plain outline.
	if got := cf.GlyphType(2); got != GlyphTypeCOLR {
		t.Errorf("GlyphType(2) = %v, want COLR", got)
	}
	if got := cf.GlyphType(0); got != GlyphTypeOutline {
		t.Errorf("GlyphType(0) = %v, want Outline", got)
	}
	// Unknown glyph ids stay outlines, never panic.
	if got := cf.GlyphType(60000); got != GlyphTypeOutline {
		t.Errorf("GlyphType(60000) = %v, want Outline", got)
	}
}

func TestCOLR_MultilayerPixelsAndOrder(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)
	face := src.Face(48)

	dst := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(dst, string(colrTestRune), face, 10, 70, color.Black)

	if n := countAlphaPixels(dst); n == 0 {
		t.Fatal("COLR glyph painted nothing")
	}

	box := paintedBounds(dst)
	// Outer-only corner: palette-0 entry 0 is opaque blue (R0 G0 B255).
	outer := dst.RGBAAt(box.Min.X+1, box.Min.Y+1)
	if outer.B != 255 || outer.R != 0 || outer.A != 255 {
		t.Errorf("outer-only pixel = %+v, want opaque blue", outer)
	}

	// Center is covered by all three layers; the foreground (black) is the
	// topmost layer so it must win.
	cx, cy := (box.Min.X+box.Max.X)/2, (box.Min.Y+box.Max.Y)/2
	center := dst.RGBAAt(cx, cy)
	if center != (color.RGBA{R: 0, G: 0, B: 0, A: 255}) {
		t.Errorf("center = %+v, want opaque black from foreground layer", center)
	}

	// A point in the middle ring shows the 50%-alpha green layer composited
	// over blue: fully opaque after over-compositing with a real green
	// contribution (exactly 128 where AA coverage is complete, lower on
	// fringe pixels).
	mid := dst.RGBAAt(box.Min.X+6, cy)
	if mid.A != 255 {
		t.Errorf("mid ring alpha = %d, want 255 after over-composite", mid.A)
	}
	if mid.G == 0 || mid.G > 128 {
		t.Errorf("mid ring green = %d, want a blended value in (0,128]", mid.G)
	}
	// And it must differ from the pure-blue outer ring, proving the second
	// layer actually contributed.
	if mid == outer {
		t.Error("mid ring equals outer layer: layer compositing missing")
	}
}

func TestCOLR_PaletteSwitch(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)

	render := func(palette int) color.RGBA {
		face := src.Face(48, WithColorPalette(palette))
		dst := image.NewRGBA(image.Rect(0, 0, 200, 120))
		DrawWithEmoji(dst, string(colrTestRune), face, 10, 70, color.Black)
		box := paintedBounds(dst)
		return dst.RGBAAt(box.Min.X+1, box.Min.Y+1)
	}

	p0 := render(0)
	p1 := render(1)
	// Palette 0 entry0 is blue (R0 G0 B255); palette 1 entry0 is red
	// (R255 G0 B0).
	if p0.B != 255 || p0.R != 0 {
		t.Errorf("palette 0 outer = %+v, want blue", p0)
	}
	if p1.R != 255 || p1.B != 0 {
		t.Errorf("palette 1 outer = %+v, want red", p1)
	}

	// Out-of-range palette indices fall back to palette 0, no panic.
	face := src.Face(48, WithColorPalette(99))
	dst := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(dst, string(colrTestRune), face, 10, 70, color.Black)
	box := paintedBounds(dst)
	if got := dst.RGBAAt(box.Min.X+1, box.Min.Y+1); got != p0 {
		t.Errorf("palette 99 fallback = %+v, want palette0 %+v", got, p0)
	}
}

func TestCOLR_ForegroundColorOverride(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)
	face := src.Face(48)

	centerPixel := func(img *image.RGBA) color.RGBA {
		box := paintedBounds(img)
		return img.RGBAAt((box.Min.X+box.Max.X)/2, (box.Min.Y+box.Max.Y)/2)
	}

	dst := image.NewRGBA(image.Rect(0, 0, 200, 120))
	// Magenta foreground applies only to the 0xFFFF inner-square layer.
	DrawWithEmojiOptions(dst, string(colrTestRune), face, 10, 70, color.Black, EmojiOptions{
		Foreground: color.RGBA{R: 255, B: 255, A: 255},
	})
	inner := centerPixel(dst)
	if inner.R == 0 || inner.B == 0 {
		t.Errorf("inner pixel %+v missing magenta foreground", inner)
	}

	// Default foreground comes from the draw color argument.
	dst2 := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(dst2, string(colrTestRune), face, 10, 70, color.RGBA{R: 255, G: 255, A: 255})
	inner2 := centerPixel(dst2)
	if inner2.R == 0 || inner2.G == 0 {
		t.Errorf("default white foreground not applied: %+v", inner2)
	}
}

func TestCOLR_Alpha(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)
	face := src.Face(48)

	full := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(full, string(colrTestRune), face, 10, 70, color.Black)
	box := paintedBounds(full)
	fullOuter := full.RGBAAt(box.Min.X+1, box.Min.Y+1)

	half := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmojiOptions(half, string(colrTestRune), face, 10, 70, color.Black, EmojiOptions{Alpha: 0.5})
	halfOuter := half.RGBAAt(box.Min.X+1, box.Min.Y+1)

	if fullOuter.A != 255 {
		t.Fatalf("baseline alpha = %d, want 255", fullOuter.A)
	}
	if halfOuter.A < 126 || halfOuter.A > 129 {
		t.Errorf("half-alpha outer A = %d, want ~128", halfOuter.A)
	}
}

func TestCOLR_TransparentPaletteEntrySkipped(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)
	parsed := src.Parsed()
	cf := parsed.(ColorFont)

	// gid 6 (U+E001) is a single layer using palette entry 2 (alpha 0).
	g, err := cf.COLRGlyph(6, 0)
	if err != nil {
		t.Fatalf("COLRGlyph(6): %v", err)
	}
	if !g.Layers[0].IsTransparent() {
		t.Fatal("U+E001 layer should resolve to a transparent palette color")
	}

	face := src.Face(48)
	dst := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(dst, string(colrTransparentRune), face, 10, 70, color.Black)
	if n := countAlphaPixels(dst); n != 0 {
		t.Errorf("transparent-only glyph painted %d pixels, want 0", n)
	}
}

func TestCOLR_ScalingKeepsStackAligned(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)

	sizes := []float64{16, 48, 96}
	var prevBox image.Rectangle
	for i, size := range sizes {
		face := src.Face(size)
		dst := image.NewRGBA(image.Rect(0, 0, 400, 200))
		DrawWithEmoji(dst, string(colrTestRune), face, 10, 120, color.Black)

		box := paintedBounds(dst)
		if box.Empty() {
			t.Fatalf("size %v: nothing painted", size)
		}
		if i > 0 {
			// Larger ppem must produce a strictly larger ink box.
			if box.Dx() <= prevBox.Dx() || box.Dy() <= prevBox.Dy() {
				t.Errorf("size %v box %v did not grow beyond %v", size, box, prevBox)
			}
		}
		prevBox = box
	}
}

func TestCOLR_FractionalOriginAlignment(t *testing.T) {
	src := loadCOLRSource(t, colrSynthFixture)
	face := src.Face(48)

	integer := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(integer, string(colrTestRune), face, 10, 70, color.Black)

	fractional := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(fractional, string(colrTestRune), face, 10.5, 70.25, color.Black)

	ib := paintedBounds(integer)
	fb := paintedBounds(fractional)
	if fb.Empty() || ib.Empty() {
		t.Fatal("expected paint at both origins")
	}
	// Subpixel shift moves the ink box by roughly the fractional offset;
	// dimensions stay within one pixel of each other.
	if d := absInt(fb.Dx() - ib.Dx()); d > 1 {
		t.Errorf("fractional origin changed width by %d (ib=%v fb=%v)", d, ib, fb)
	}
	if d := absInt(fb.Dy() - ib.Dy()); d > 1 {
		t.Errorf("fractional origin changed height by %d (ib=%v fb=%v)", d, ib, fb)
	}
}

func TestCOLR_AdvanceMatchesMonochrome(t *testing.T) {
	src := loadCOLRSource(t, colrPixelsFixture)
	face := src.Face(32)
	text := "A-._"

	want := face.Advance(text)

	// Glyph ink may overhang the advance slightly (bearing + AA fringe);
	// the point is that rendering four glyphs stays inside a window derived
	// from the measured advance plus the small rasterization margin, rather
	// than drifting by whole glyph widths.
	dst := image.NewRGBA(image.Rect(0, 0, 400, 120))
	DrawWithEmoji(dst, text, face, 0, 80, color.Black)
	box := paintedBounds(dst)
	if box.Empty() {
		t.Fatal("nothing rendered")
	}
	if float64(box.Max.X) > want+8 {
		t.Errorf("ink extends to %d but measured advance is %v", box.Max.X, want)
	}

	// The cursor must equal the monochrome advance exactly: render the same
	// string through Draw and compare the rightmost ink edge — both paths
	// consume the same per-glyph advances.
	mono := image.NewRGBA(image.Rect(0, 0, 400, 120))
	Draw(mono, text, face, 0, 80, color.Black)
	monoBox := paintedBounds(mono)
	if d := absInt(box.Max.X - monoBox.Max.X); d > 4 {
		t.Errorf("color path edge %d vs monochrome %d differ by %d; advance drift",
			box.Max.X, monoBox.Max.X, d)
	}
}

func TestCOLR_MultiFaceFallback(t *testing.T) {
	// Plain font covers 'A'; COLR font covers U+E000. MultiFace must render
	// each rune with the owning face and keep a single continuous cursor.
	plainSrc, err := NewFontSource(requireTestFont(t))
	if err != nil {
		t.Fatalf("plain font: %v", err)
	}
	t.Cleanup(func() { _ = plainSrc.Close() })
	colrSrc := loadCOLRSource(t, colrSynthFixture)

	mf, err := NewMultiFace(plainSrc.Face(40), colrSrc.Face(40))
	if err != nil {
		t.Fatalf("NewMultiFace: %v", err)
	}

	dst := image.NewRGBA(image.Rect(0, 0, 400, 120))
	// 'A' from the plain face followed by the COLR private-use glyph.
	DrawWithEmoji(dst, "A" + string(colrTestRune), mf, 10, 80, color.Black)
	if n := countAlphaPixels(dst); n == 0 {
		t.Fatal("MultiFace rendered nothing")
	}

	// The color glyph's blue outer layer must appear (proving the COLR face
	// was selected for the second rune, not monochrome fallback).
	foundBlue := false
	b := dst.Bounds()
	for y := b.Min.Y; y < b.Max.Y && !foundBlue; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			c := dst.RGBAAt(x, y)
			if c.B == 255 && c.R == 0 && c.A == 255 {
				foundBlue = true
				break
			}
		}
	}
	if !foundBlue {
		t.Error("COLR layer color absent: MultiFace did not route to the color face")
	}
}

func TestCOLR_PlainFontBehaviorUnchanged(t *testing.T) {
	// A font without color tables must take the identical monochrome path:
	// same pixels for Draw and DrawWithEmoji.
	src, err := NewFontSource(requireTestFont(t))
	if err != nil {
		t.Fatalf("font load: %v", err)
	}
	t.Cleanup(func() { _ = src.Close() })
	face := src.Face(20)

	one := image.NewRGBA(image.Rect(0, 0, 300, 60))
	Draw(one, "Hello", face, 5, 40, color.Black)

	two := image.NewRGBA(image.Rect(0, 0, 300, 60))
	DrawWithEmoji(two, "Hello", face, 5, 40, color.Black)

	if !imagesEqual(one, two) {
		t.Error("Draw and DrawWithEmoji differ on a non-color font")
	}
}

func TestCOLR_MalformedFontFallsBackWithoutPanic(t *testing.T) {
	// Truncate the COLR table inside the raw font bytes. The face must still
	// load and rendering must degrade to monochrome, never panic.
	data, err := os.ReadFile(colrSynthFixture)
	if err != nil {
		t.Skipf("fixture read: %v", err)
	}
	corrupt := cloneBytes(data)
	// Locate the COLR table via the directory and cut it to its header only.
	if off, length, ok := findTableRange(corrupt, "COLR"); ok {
		for i := off + 14; i < off+length; i++ {
			corrupt[i] = 0
		}
	}

	src, err := NewFontSource(corrupt)
	if err != nil {
		// A hard parse error is also acceptable as long as it is not a panic.
		return
	}
	t.Cleanup(func() { _ = src.Close() })
	face := src.Face(48)

	dst := image.NewRGBA(image.Rect(0, 0, 200, 120))
	DrawWithEmoji(dst, string(colrTestRune), face, 10, 70, color.Black) // must not panic
}

// --- helpers ---

func paintedBounds(img *image.RGBA) image.Rectangle {
	b := img.Bounds()
	minX, minY := b.Max.X, b.Max.Y
	maxX, maxY := b.Min.X, b.Min.Y
	found := false
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			if img.RGBAAt(x, y).A == 0 {
				continue
			}
			found = true
			if x < minX {
				minX = x
			}
			if x+1 > maxX {
				maxX = x + 1
			}
			if y < minY {
				minY = y
			}
			if y+1 > maxY {
				maxY = y + 1
			}
		}
	}
	if !found {
		return image.Rectangle{}
	}
	return image.Rect(minX, minY, maxX, maxY)
}

func absInt(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

func imagesEqual(a, b *image.RGBA) bool {
	if a.Bounds() != b.Bounds() {
		return false
	}
	for i := range a.Pix {
		if a.Pix[i] != b.Pix[i] {
			return false
		}
	}
	return true
}

func cloneBytes(in []byte) []byte {
	out := make([]byte, len(in))
	copy(out, in)
	return out
}

// findTableRange returns the byte offset and length of an sfnt table.
func findTableRange(data []byte, tag string) (int, int, bool) {
	if len(data) < 12 {
		return 0, 0, false
	}
	numTables := int(uint16(data[4])<<8 | uint16(data[5]))
	for i := 0; i < numTables; i++ {
		rec := 12 + i*16
		if rec+16 > len(data) {
			return 0, 0, false
		}
		if string(data[rec:rec+4]) == tag {
			off := int(uint32(data[rec+8])<<24 | uint32(data[rec+9])<<16 |
				uint32(data[rec+10])<<8 | uint32(data[rec+11]))
			length := int(uint32(data[rec+12])<<24 | uint32(data[rec+13])<<16 |
				uint32(data[rec+14])<<8 | uint32(data[rec+15]))
			return off, length, true
		}
	}
	return 0, 0, false
}
